import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedbackQuestions, setFeedbackQuestions] = useState([
    { id: 1, question: 'How was the instructor?', options: ['Excellent', 'Good', 'Fair', 'Poor'] },
    { id: 2, question: 'How was the course material?', options: ['Excellent', 'Good', 'Fair', 'Poor'] },
    { id: 3, question: 'Would you recommend this course?', options: ['Yes', 'No', 'Undecided'] },
  ]);

  const [feedbackAnswers, setFeedbackAnswers] = useState({});

  const handleAnswerChange = (id, answer) => {
    setFeedbackAnswers((prevAnswers) => ({ ...prevAnswers, [id]: answer }));
  };

