  const [text, setText] = useState('');

  const chips = [
    { id: 1, label: 'Chip 1' },
    { id: 2, label: 'Chip 2' },
    { id: 3, label: 'Chip 3' },
  ];

  const handleChipPress = (chipId) => {
    const chipLabel = chips.find((chip) => chip.id === chipId).label;
    setText(text + ' ' + chipLabel);
  };

  return (
