      <TextInput
        value={text}
        onChangeText={(text) => setText(text)}
        placeholder="Type something"
      />
      {chips.map((chip) => (
        <TouchableHighlight key={chip.id} onPress={() => handleChipPress(chip.id)}>
          <View>
            <Text>{chip.label}</Text>
          </View>
        </TouchableHighlight>
      ))}
    </View>
  );
};

export default App;
```
