import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

const Carousel = (props) => {
  const [queries, setQueries] = useState([]);
  const [images, setImages] = useState([]);
  const [ slicedImages, setSlicedImages ] = useState([]);
  const [activeSlide, setActiveSlide] = useState(0);

  useEffect(() => {
    const loadImages = async () => {
      const imagePromises = queries.map((query) => {
        const url = `https://api.unsplash.com/search/photos?query=${query}&orientation=landscape&per_page=3&client_id=YOUR_UNSPLASH_API_KEY`;
        return axios.get(url);
      });
      const images = await Promise.all(imagePromises);
      setImages(images.map((image) => image.data.results));
    };
    loadImages();
  }, [queries]);

  useEffect(() => {
    setSlicedImages(images.slice(activeSlide * 3, (activeSlide + 1) * 3));
  }, [activeSlide, images]);

  const settings = {
    dots: true,
    infinite: true,
    arrows: false,
    autoplay: true,
    autoplaySpeed: 3000,
  };

  return (
    <div>
      <Slider {...settings}>
        {slicedImages.map((image, index) => (
          <div key={index}>
            <img
              src={image.urls.regular}
              alt={image.description}
              onLoad={() => {
                // lazy load the next image when this one is loaded
                if (index < slicedImages.length - 1) {
                  const nextImage = slicedImages[index + 1];
                  const nextImageElement = document.getElementById(
                    `image-${nextImage.id}`
                  );
                  nextImageElement.src = nextImage.urls.regular;
                }
              }}
              id={`image-${image.id}`}
            />
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default Carousel;
