```
using System;
using System.Net.Mail;
using System.Net;
using System.Collections.Generic;

namespace EmailSender
{
    class Program
    {
        static List<string> subscribers = new List<string>();
        static List<MailAddress> emailAccounts = new List<MailAddress>();

        static void Main(string[] args)
        {
            // Add subscribers' email addresses
            for (int i = 0; i < 100; i++)
            {
                subscribers.Add($"subscriber_{i}@example.com");
            }

            // Add email accounts to rotate
            emailAccounts.Add(new MailAddress("email1@example.com", "Email Account 1"));
            emailAccounts.Add(new MailAddress("email2@example.com", "Email Account 2"));
            emailAccounts.Add(new MailAddress("email3@example.com", "Email Account 3"));

            foreach (var subscriber in subscribers)
            {
                SendEmail(subscriber);
            }
        }

        static void SendEmail(string subscriberEmail)
        {
            // Choose an email account for this iteration
            int accountIndex = (int)(DateTime.Now.Ticks % emailAccounts.Count);
            MailAddress emailAccount = emailAccounts[accountIndex];

            // Create a new MailMessage
            MailMessage mail = new MailMessage();
            mail.From = emailAccount;
            mail.To.Add(subscriberEmail);
            mail.Subject = "Hello from Email Sender!";
            mail.Body = "This is a test email sent using the email sender application.";

            // Send the email using SmtpClient
            SmtpClient client = new SmtpClient();
            client.Send(mail);
        }
    }
}
```
