Here is a generic Java code snippet to convert SQL queries to MongoDB queries:
```java
import com.mongodb.MongoClient;
import com.mongodb.client.MongoCollection;
import com.mongodb.client.MongoDatabase;
import com.mongodb.client.model.Filters;
import com.mongodb.client.model.Sorts;
import com.mongodb.client.model.Updates;

import org.bson.Document;
import org.bson.conversions.Bson;
import org.bson.types.ObjectId;

import java.util.ArrayList;
import java.util.List;

public class SQLtoMongoConverter {
    private MongoClient mongoClient;
    private MongoDatabase database;
    private MongoCollection<Document> collection;

    public SQLtoMongoConverter(String mongoUrl, String dbName, String collectionName) {
        mongoClient = new MongoClient(mongoUrl);
        database = mongoClient.getDatabase(dbName);
        collection = database.getCollection(collectionName, Document.class);
    }

    public Bson convertSQLtoMongo(String sqlQuery) {
        sqlQuery = sqlQuery.trim().toLowerCase();

        // Handle SELECT queries
        if (sqlQuery.startsWith("select")) {
            String[] queries = sqlQuery.split(" from ");
            String table = queries[1].trim();
            List<Bson> filters = new ArrayList<>();

            // Handle WHERE clause
            if (queries.length > 2 && queries[2].startsWith("where")) {
                String[] whereClauses = queries[2].split(" and ");
                for (String clause : whereClauses) {
                    if (clause.startsWith("=")) {
                        String key = clause.split("=")[0].trim();
                        String value = clause.split("=")[1].trim();
                        filters.add(Filters.eq(key, value));
                    } else if (clause.startsWith(">")) {
                        String key = clause.split(">")[0].trim();
                        String value = clause.split(">")[1].trim();
                        filters.add(Filters.gt(key, value));
                    } else if (clause.startsWith("<")) {
                        String key = clause.split("<")[0].trim();
                        String value = clause.split("<")[1].trim();
                        filters.add(Filters.lt(key, value));
                    } else if (clause.startsWith("<>")) {
                        String key = clause.split("<>")[0].trim();
                        String value = clause.split("<>")[1].trim();
                        filters.add(Filters.ne(key, value));
                    }
                }
            }

            // Handle SORT clause
            if (queries.length > 2 && queries[2].contains(" order by ")) {
                String[] orderByClauses = queries[2].split(" order by ");
                String sortBy = orderByClauses[1];
                String sortOrder = orderByClauses[2].trim();
                if (sortOrder.equals("asc")) {
                    if (sortBy.contains(".")) {
                        String field = sortBy.split("\\.")[1];
                        filters.add(Sorts.ascending(field));
                    } else {
                        filters.add(Sorts.ascending(sortBy));
                    }
                } else if (sortOrder.equals("desc")) {
                    if (sortBy.contains(".")) {
                        String field = sortBy.split("\\.")[1];
                        filters.add(Sorts.descending(field));
                    } else {
                        filters.add(Sorts.descending(sortBy));
                    }
                }
            }

            // Convert filters to BSON
            Bson filter = Filters.and(filters);
            return filter;
        }

        // Handle INSERT queries
        else if (sqlQuery.startsWith("insert")) {
            String[] queries = sqlQuery.split(" into ");
            String tableName = queries[1].trim();
            Document document = new Document();
            // Convert each column-value pair to a Document
            String[] columns = queries[0].split(",");
            for (int i = 0; i < columns.length; i++) {
                String[] columnValuePair = columns[i].trim().split("=");
                String key = columnValuePair[0].trim();
                String value = columnValuePair[1].trim();
                document.append(key, value);
            }
            return Updates.insertOne(new Document(tableName, document));
        }

        // Handle UPDATE queries
        else if (sqlQuery.startsWith("update")) {
            String[] queries = sqlQuery.split(" set ");
            String tableName = queries[0].trim();
            Document document = new Document();
            // Convert each column-value pair to a Document
            String[] updates = queries[1].split(",");
            for (int i = 0; i < updates.length; i++) {
                String[] columnValuePair = updates[i].trim().split("=");
                String key = columnValuePair[0].trim();
                String value = columnValuePair[1].trim();
                document.append(key, value);
            }
            String[] conditions = queries[2].split(" where ");
            return Updates.updateMany(Filters.eq(tableName, conditions[1].trim()), Updates.set(document));
        }

        // Handle DELETE queries
        else if (sqlQuery.startsWith("delete")) {
            String[] queries = sqlQuery.split(" from ");
            String tableName = queries[1].trim();
            String[] conditions = queries[2].split(" where ");
            return Deletes.deleteMany(Filters.eq(tableName, conditions[1].trim()));
        }

        return null;
    }

    public void close() {
        mongoClient.close();
    }
}
```
