Here is a C++ program that patches the specified bytes in an executable application:
```cpp
#include <cstdio>
#include <iostream>
#include <fstream>
#include <iomanip>
#include <vector>

using namespace std;

int main() {
    // Input file name
    string inputFileName = "path/to/your/executable.exe";

    // Output file name
    string outputFileName = "patched.exe";

    // Patch locations and values
    vector<pair<unsigned long, char>> patches = {
        {0x002D32CC, (char)0xEB},  // 75 -> EB
        {0x002D32CD, (char)0x42}  // 47 -> 42
    };

    // Open input file
    ifstream inputFile(inputFileName, ios::binary | ios::in);
    if (!inputFile) {
        cerr << "Error: unable to open input file." << endl;
        return 1;
    }

    // Open output file
    ofstream outputFile(outputFileName, ios::binary | ios::out);
    if (!outputFile) {
        cerr << "Error: unable to open output file." << endl;
        return 1;
    }

    // Patch the input file
    unsigned long fileSize = inputFile.tellg();
    inputFile.seekg(0, ios::beg);
    char buffer[1024];
    while (inputFile.read(buffer, sizeof(buffer))) {
        for (auto& patch : patches) {
            if (inputFile.tellg() == patch.first) {
                outputFile.put(patch.second);
            } else {
                outputFile.put(buffer[0]);
            }
        }
        outputFile.write(buffer, sizeof(buffer));
    }

    // Write any remaining bytes
    inputFile.seekg(0, ios::end);
    outputFile.seekp(0, ios::end);
    outputFile.write((char*)&fileSize, sizeof(fileSize));

    // Close files
    inputFile.close();
    outputFile.close();

    cout << "Patching complete. Output file: " << outputFileName << endl;

    return 0;
}
```
This program takes an input file name and output file name as command-line arguments. It reads the input file in binary mode and patches the specified locations by replacing the original bytes with the new values.

Note that this program assumes that the input file is a PE (Portable Executable) file, and the patch locations are specified in hexadecimal format. The program also assumes that the input file is not encrypted or compressed.

To use this program, simply compile it and run it with the input file name and output file name as command-line arguments:
```
$ ./patcher input.exe output.exe
```
